function applyPdfSource(p,data,label){clearSourceFigureUrls();const rec=buildPdfRecord(data,label);const prev=state.src[p.id];rec.gen=((prev&&prev.gen)||0)+1;state.src[p.id]=rec;state.pdfView='text';renderMain();}
